export function destroyEphemeralL1({ target, root, force = false, policy = readPolicy() } = {}) {
  if (!target) throw new Error("destroy requires a root");
  if (force) {
    // A valid marker is stronger provenance than heuristic layout evidence.
    // Only fall back to stranded-mission recovery when the marker is absent
    // or cannot be parsed/validated.
    const configuredRoot = realpathSync(root || policy.root);
    assertOwnerPrivate(lstatSync(configuredRoot), "configured ephemeral root");
    const candidate = path.resolve(target);
    if (path.dirname(candidate) !== configuredRoot) throw new Error("destroy target must be one direct child of the configured root");
    const targetInfo = lstatSync(candidate);
    if (targetInfo.isSymbolicLink()) throw new Error("destroy target must not be a symlink");
    assertOwnerPrivate(targetInfo, "destroy target");
    if (realpathSync(candidate) !== candidate) throw new Error("destroy target is not canonical");

    const markerPath = path.join(candidate, policy.marker);
    let validated;
    try {
      validated = readValidatedMarker(candidate, configuredRoot, policy);
    } catch (error) {
      // A marker with the expected identity is a real mission marker whose
      // lifecycle/layout checks failed (for example, active or malformed
      // paths); never downgrade that refusal to heuristic deletion.
      try {
        const marker = JSON.parse(readFileSync(markerPath, "utf8"));
        if (plainObject(marker, "destroy marker").schema === policy.markerSchema
          && marker.root === candidate) throw error;
      } catch (markerError) {
        if (markerError === error) throw error;
      }
    }
    if (validated) {
      try { chmodSync(candidate, 0o700); } catch { /* best-effort */ }
    } else {
      const canonicalPrivateDirectory = (name) => {
        const location = path.join(candidate, name);
        const info = lstatSync(location);
        if (info.isSymbolicLink() || !info.isDirectory()) throw new Error(`destroy ${name} must be a canonical private directory`);
        assertOwnerPrivate(info, `destroy ${name}`);
        if (realpathSync(location) !== location) throw new Error(`destroy ${name} is not canonical`);
        return location;
      };
      const checkout = canonicalPrivateDirectory("checkout");
      const isolation = canonicalPrivateDirectory("isolation");
      let expectedStructure = false;
      try {
        const gitInfo = lstatSync(path.join(checkout, ".git"));
        expectedStructure = gitInfo.isDirectory() && !gitInfo.isSymbolicLink();
      } catch { /* missing checkout structure */ }
      try {
        const envInfo = lstatSync(path.join(isolation, "environment.json"));
        expectedStructure ||= envInfo.isFile() && !envInfo.isSymbolicLink();
      } catch { /* missing isolation structure */ }
      if (!expectedStructure) {
        throw new Error("destroy target shows no expected ephemeral mission structure");
      }
    }
    // Restore write permission so rmSync can traverse permission-starved debris.
    try { chmodSync(candidate, 0o700); } catch { /* best-effort */ }
    const chmodSweep = (dir) => {
      for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, entry.name);
        try {
          // Never chmod a symlink: chmodSync follows the link and would
          // rewrite the TARGET's mode — a planted link escapes the ephemeral
          // root and chmods host files (r01 SwarmReviewer33 F1).
          if (entry.isSymbolicLink()) continue;
          if (entry.isDirectory()) { chmodSync(p, 0o700); chmodSweep(p); }
          else chmodSync(p, 0o600);
        } catch { /* best-effort sweep */ }
      }
    };
    try { chmodSweep(candidate); } catch { /* best-effort sweep */ }
    rmSync(candidate, { recursive: true, force: true });

