function expandTemplate(value, token, base) {
  const prefix = `\${${token}}`;
  if (!value.startsWith(`${prefix}/`)) fail(`invalid ${token} template`);
  const expanded = path.normalize(`${base}${value.slice(prefix.length)}`);
  if (!expanded.startsWith(`${base}${path.sep}`)) fail(`${token} template escapes its base`);
  return expanded;

