export function correlationGroup(role, lineage, resolvedModel) {
  assertSafeRole(role);
  // Hash inputs must be strings: a non-string resolvedModel/lineage would
  // coerce (null→"null", 1→"1") and collide across typed values.
  if (typeof resolvedModel !== "string" || typeof lineage !== "string") {
    throw new Error(`invalid correlation inputs ${JSON.stringify({ resolvedModel, lineage })}`);
  }
  const digest = createHash("sha256")
    .update(`omp-native-correlation-v1\u0000${resolvedModel}\u0000${role}\u0000${lineage}`)
    .digest("hex");
  return `sha256:${digest}`;

export function unavailabilityGroup(role, resolvedModel) {
  assertSafeRole(role);
  if (typeof resolvedModel !== "string") {
    throw new Error(`invalid unavailability input ${JSON.stringify(resolvedModel)}`);
  }
  const digest = createHash("sha256")
    .update(`omp-native-unavailability-v1\u0000${resolvedModel}\u0000${role}`)
    .digest("hex");
  return `sha256:${digest}`;

function assertSafeRole(role) {
  // Role enters seatId/label/dispatch paths and correlation digests. Reject
  // NUL, CR/LF, and other C0 controls so labels stay path/JSON-safe and
  // injectivity with Rust twins is not lost to invisible bytes.
  if (typeof role !== "string" || /[\u0000-\u001f\u007f]/.test(role)) {
    throw new Error(`invalid seat role ${JSON.stringify(role)}`);
