    ownerPid = Number.isSafeInteger(parsed) ? parsed : null;
  } catch {
    // Absent, unreadable (planted link), or malformed: no live owner evidence.
    ownerPid = null;
  }
  return { ownerPid, live: ownerPid !== null && alive(ownerPid) };
}

