  const dir = join(state, "sessions", RUN);
  mkdirSync(dir, { recursive: true });
  writeBig(join(dir, "1.bash.log"), 150 * MiB);
  const queueFifo = join(state, "pending-work.json");
  assert.equal(spawnSync("mkfifo", [queueFifo]).status, 0);

  const sweep = cli(["sweep", "--now", new Date(NOW).toISOString()], { state, timeout: 2000 });
  assert.equal(sweep.status, 0, JSON.stringify(sweep.error));
  assert.equal(sweep.json.guardSources.queue, "queue_unsafe");
  assert.ok(sweep.json.events.some((event) => event.event === "retention_guard_source_unavailable"));

assert.equal(spawnSync("mkfifo", [logFifo]).status, 0);
const cap = cli(["cap", "--session-dir", dir, "--apply"], { state, timeout: 2000 });
assert.equal(cap.status, 0, JSON.stringify(cap.error));
assert.equal(cap.json.capped, 1, "telemetry loss never blocks the retention work");
assert.equal(statSync(join(dir, "1.bash.log")).size, CAP);
assert.ok(statSync(logFifo).isFIFO(), "the squatter is never replaced or written through");

