test("cache TTL is decoupled from the poll cadence", () => {
  const now = 1_000_000;
  // The old 5s TTL could never serve a lone session: its next tick lands at
  // (or just after) 5,000ms. 5,000 and 9,999 must still be hits.
  assert.equal(isCacheFresh(now - 4_999, now), true);
  assert.equal(isCacheFresh(now - 5_000, now), true);
  assert.equal(isCacheFresh(now - 9_999, now), true);
  assert.equal(isCacheFresh(now - 10_000, now), false);
  assert.equal(isCacheFresh(now + 1_000, now), true);
  assert.equal(isCacheFresh(now + 1_001, now), false);
  assert.equal(isCacheFresh("nope", now), false);
  assert.equal(isCacheFresh(Number.NaN, now), false);
});

test("display stamp only follows a confirmed full refresh", () => {
  assert.equal(shouldStampDisplayRefresh(false, { displayRefreshed: true }), true);
  assert.equal(shouldStampDisplayRefresh(false, { displayRefreshed: false }), false);
  assert.equal(shouldStampDisplayRefresh(false, {}), false);
  assert.equal(shouldStampDisplayRefresh(false, null), false);
  // --lite never refreshes by design, even if a producer wrote true.
  assert.equal(shouldStampDisplayRefresh(true, { displayRefreshed: true }), false);
});

