const CREDENTIAL_SHAPE = /(?:authorization|proxy-authorization)\s*[:=]|bearer\s+[A-Za-z0-9._~+-]+|basic\s+[A-Za-z0-9+\/=]{10,}|(?:api[_-]?key|secret|password|token)\s*[:=]|(?:sk|rk|ak|xai)-[A-Za-z0-9_-]{12,}|-----BEGIN [A-Z ]*PRIVATE KEY-----/iu;
const REDACT_PATTERNS = [
  // Key=value pairs with credential-like keys: capture the key and separator,
  // replace the value — a key-only match would leave the secret verbatim
  // (fleet-dispatcher.mjs parity). The value runs to the next quote, comma,
  // brace, or newline — NOT the next space: `session_key: my secret` must
  // lose the whole tail, not just the first word.
  /("?(?:authorization|proxy-authorization|token|access_token|refresh_token|api[_-]?key|secret[_-]?key|private[_-]?key|password|bearer_token|client_secret|session_key|signing_key|private_token|cookie|set-cookie)"?\s*[:=]\s*"?)([^"\n},]{1,})/giu,
  // PEM blocks and basic-auth blobs run BEFORE CREDENTIAL_SHAPE — the shape
  // regex matches their markers alone and would leave the body behind.
  /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/gu,
  /(\bbasic\s+)[A-Za-z0-9+\/=]{10,}/giu,
  CREDENTIAL_SHAPE,
  /\beyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g,
  // Whole cookie header value, not just the first pair: a second pair would
  // otherwise survive verbatim.
  /\b(?:cookie|set-cookie)\s*[:=]\s*[^\n]+/gi,
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
  /\b(?:sk|rk|ak|xai)-[A-Za-z0-9_-]{12,}/gi,
  /(?<![A-Za-z0-9_-])(?:ghp|gho|ghu|ghs|ghr|xghp)_[A-Za-z0-9_-]{12,}/gi,
  /(?<![A-Za-z0-9_-])github_pat_[A-Za-z0-9_-]{12,}/gi,
  /(?<![A-Za-z0-9_-])(?:AKIA|ASIA)[A-Z0-9]{16}\b/g,
